class Solution {
public:
    long long countBadPairs(std::vector<int>& nums) {
        long long n = nums.size();
        long long total_pairs = n * (n - 1) / 2;
        std::unordered_map<int, long long> counts;
        long long good_pairs = 0;
        for (int i = 0; i < n; ++i) {
            int diff = nums[i] - i;
            good_pairs += counts[diff];
            counts[diff]++;
        }
        return total_pairs - good_pairs;
    }
};

class Solution {
    public long countBadPairs(int[] nums) {
        long n = nums.length;
        long totalPairs = n * (n - 1) / 2;
        java.util.Map<Integer, Long> counts = new java.util.HashMap<>();
        long goodPairs = 0;
        for (int i = 0; i < n; ++i) {
            int diff = nums[i] - i;
            long cnt = counts.getOrDefault(diff, 0L);
            goodPairs += cnt;
            counts.put(diff, cnt + 1);
        }
        return totalPairs - goodPairs;
    }
}

